  lab_f_isspass_azimuth: "Aufgang bei (Kompass °)",
  lab_f_isspass_date: "Ab Datum",
  lab_f_isspass_err_input: "Gib einen gültigen Ort und ein gültiges Datum ein.",
  lab_f_isspass_err_none: "Von hier aus kein Überflug über 10° in den nächsten 48 Stunden — versuch ein anderes Datum oder einen anderen Ort.",
  lab_f_isspass_in_words: "Keine geschlossene Formel hier: propagiere die aktuelle TLE voraus und finde den nächsten Zeitpunkt, wenn die ISS über 10° an deinem Ort aufsteigt. Die Sichtbarkeitsfenster-Karte sagte, ein Überflug existiert — diese sagt WANN.",
  lab_f_isspass_latitude: "Deine geografische Breite",
